import XCTest
@testable import WeddingCore

final class WeddingTests:XCTestCase {
    func testMoneyExactAndLocale() throws {XCTAssertEqual(try Money.parse("1200,05",currency:"EUR"),120005);XCTAssertEqual(try Money.parse("0.01",currency:"EUR"),1);XCTAssertEqual(try Money.parse("250",currency:"JPY"),250);XCTAssertEqual(Money.input(12345,currency:"EUR"),"123,45")}
    func testMoneyRejectsAmbiguityAndOverflow() {for v in ["1.234,56","-1","nan","1e3","1,234","","1 000","1000000000000000000"] {XCTAssertThrowsError(try Money.parse(v,currency:"EUR"),v)};XCTAssertThrowsError(try Money.parse("1.5",currency:"JPY"))}
    func testBudgetQuoteReplacesPlanNotAdds() {var db = WeddingArchive();db.settings.budget = 100000;db.expenses = [Expense(title:"Fiori",planned:30000,quote:25000,payments:[Payment(amount:10000)])];db.vendors = [Vendor(name:"Fiorista",cost:25000)];XCTAssertEqual(db.planned,30000);XCTAssertEqual(db.committed,25000);XCTAssertEqual(db.paid,10000);XCTAssertEqual(db.outstanding,15000);XCTAssertEqual(db.available,75000)}
    func testOverpaymentDoesNotHideOtherOutstanding() {var db = WeddingArchive();db.expenses = [Expense(title:"A",planned:100,payments:[Payment(amount:150)]),Expense(title:"B",planned:200)];XCTAssertEqual(db.outstanding,200);XCTAssertEqual(db.expenses[0].overpaid,50)}
    func testGuestsCountPeopleAndSeatsSeparately() {var db = WeddingArchive();db.guests = [Guest(name:"A",rsvp:.confirmed,companions:2),Guest(name:"B",rsvp:.pending,companions:1),Guest(name:"C",rsvp:.declined,companions:3)];XCTAssertEqual(db.guests.count,3);XCTAssertEqual(db.people(.confirmed),3);XCTAssertEqual(db.people(.declined),4);XCTAssertEqual(db.totalSeats,5);XCTAssertEqual(db.unassigned.count,2)}
    func testMovingGuestDoesNotDuplicateAndWarnsOvercapacity() throws {var db = WeddingArchive();let a = WeddingTable(name:"A",capacity:1);let b = WeddingTable(name:"B",capacity:2);let g = Guest(name:"Nucleo",companions:2);db.tables = [a,b];db.guests = [g];try db.assign(g.id,to:a.id);XCTAssertEqual(db.seats(a.id),3);XCTAssertEqual(db.freeSeats(a.id),0);try db.assign(g.id,to:b.id);XCTAssertEqual(db.seats(a.id),0);XCTAssertEqual(db.seats(b.id),3);XCTAssertEqual(db.guests.count,1);XCTAssertNoThrow(try db.validated())}
    func testTableDeleteUnassignsWithoutDeletingGuest() throws {var db = WeddingArchive();let t = WeddingTable(name:"A");db.tables = [t];db.guests = [Guest(name:"A",tableID:t.id)];db.deleteTable(t.id);XCTAssertNil(db.guests[0].tableID);XCTAssertEqual(db.guests.count,1);XCTAssertNoThrow(try db.validated())}
    func testAssignmentRejectsMissingReferencesAtomically() {var db = WeddingArchive();let g = Guest(name:"A");db.guests = [g];XCTAssertThrowsError(try db.assign(g.id,to:UUID()));XCTAssertNil(db.guests[0].tableID)}
    func testLinkedVendorDeletePreservesRelatedRecords() throws {var db = WeddingArchive();let v = Vendor(name:"V");db.vendors = [v];db.tasks = [WeddingTask(title:"T",vendorID:v.id)];db.expenses = [Expense(title:"E",vendorID:v.id)];db.schedule = [ScheduleEntry(title:"S",vendorID:v.id)];db.notes = [WeddingNote(title:"N",kind:.vendor,linkedID:v.id)];db.deleteVendor(v.id);XCTAssertNil(db.tasks[0].vendorID);XCTAssertNil(db.expenses[0].vendorID);XCTAssertNil(db.schedule[0].vendorID);XCTAssertEqual(db.notes[0].kind,.general);XCTAssertNoThrow(try db.validated())}
    func testGuestAndTaskDeletionPreserveNotes() throws {var db = WeddingArchive();let g = Guest(name:"G");let t = WeddingTask(title:"T");db.guests = [g];db.tasks = [t];db.notes = [WeddingNote(title:"N",kind:.guest,linkedID:g.id),WeddingNote(title:"N2",kind:.task,linkedID:t.id)];db.deleteGuest(g.id);db.deleteTask(t.id);XCTAssertTrue(db.notes.allSatisfy {$0.kind == .general && $0.linkedID == nil});XCTAssertNoThrow(try db.validated())}
    func testInvalidDuplicateIDsAndDanglingLinksRejected() {var db = WeddingArchive();let g = Guest(name:"A");db.guests = [g,g];XCTAssertThrowsError(try db.validated());db.guests = [Guest(name:"B",tableID:UUID())];XCTAssertThrowsError(try db.validated())}
    func testInvalidMoneyPositionsDatesRejected() {var db = WeddingArchive();db.tables = [WeddingTable(name:"A",x:2)];XCTAssertThrowsError(try db.validated());db.tables = [];db.settings.budget = -1;XCTAssertThrowsError(try db.validated());db.settings.budget = 0;db.tasks = [WeddingTask(title:"A",due:Date(timeIntervalSince1970:.infinity))];XCTAssertThrowsError(try db.validated())}
    func testWhitespaceTitlesAndNegativeCompanionsRejected() {var db = WeddingArchive();db.guests = [Guest(name:"   ")];XCTAssertThrowsError(try db.validated());db.guests = [Guest(name:"A",companions:-1)];XCTAssertThrowsError(try db.validated())}
    func testOverdueDoesNotIncludeDoneOrUndated() {let now = Date();var db = WeddingArchive();db.tasks = [WeddingTask(title:"Late",due:now.addingTimeInterval(-60)),WeddingTask(title:"Done",due:now.addingTimeInterval(-90),status:.done),WeddingTask(title:"Undated"),WeddingTask(title:"Next",due:now.addingTimeInterval(60))];XCTAssertEqual(db.overdue(at:now).map(\.title),["Late"])}
    func testCountdownUsesCalendarAcrossDST() {var calendar = Calendar(identifier:.gregorian);calendar.timeZone = TimeZone(identifier:"Europe/Rome")!;let from = calendar.date(from:DateComponents(year:2027,month:3,day:27,hour:23))!;let to = calendar.date(from:DateComponents(year:2027,month:3,day:29,hour:1))!;var db = WeddingArchive();db.settings.date = to;XCTAssertEqual(db.countdown(now:from,calendar:calendar),2)}
    func testScheduleDurationCrossesMidnight() {let s = ScheduleEntry(start:Date(timeIntervalSince1970:0),minutes:90);XCTAssertEqual(s.end.timeIntervalSince(s.start),5400)}
    func testCSVQuotesUnicodeMultilineAndFormulaSafety() {let csv = WeddingExport.csv([["Èva, Anna","\"Sì\"\nforse","=1+1","  @SUM(A1)"]]);XCTAssertTrue(csv.contains("\"Èva, Anna\""));XCTAssertTrue(csv.contains("\"\"Sì\"\"\nforse"));XCTAssertTrue(csv.contains("'=1+1"));XCTAssertTrue(csv.contains("'  @SUM"));XCTAssertTrue(csv.hasSuffix("\r\n"))}
    func testExportsResolveLinkedNamesAndChronology() {var db = WeddingArchive();let t = WeddingTable(name:"Rosa");db.tables = [t];db.guests = [Guest(name:"Anna",companions:1,tableID:t.id)];db.schedule = [ScheduleEntry(title:"Dopo",start:Date(timeIntervalSince1970:100)),ScheduleEntry(title:"Prima",start:Date(timeIntervalSince1970:0))];XCTAssertTrue(WeddingExport.guests(db).contains("Rosa"));let csv = WeddingExport.schedule(db);XCTAssertLessThan(csv.range(of:"Prima")!.lowerBound,csv.range(of:"Dopo")!.lowerBound)}
    private func repository() -> WeddingRepository {WeddingRepository(directory:FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString))}
    func testPersistenceBackupAndRestoreRoundTrip() throws {let r = repository();defer {try? FileManager.default.removeItem(at:r.directory)};try r.update {$0.guests = [Guest(name:"A")]};let first = try Data(contentsOf:r.file);try r.update {$0.tasks = [WeddingTask(title:"B")]};XCTAssertEqual(try r.read().tasks.count,1);XCTAssertEqual(try r.restore(first).tasks.count,0);XCTAssertEqual(try r.read().guests[0].name,"A");XCTAssertTrue(FileManager.default.fileExists(atPath:r.directory.appendingPathComponent("promessa.previous.json").path))}
    func testFailedImportLeavesArchiveByteIdentical() throws {let r = repository();defer {try? FileManager.default.removeItem(at:r.directory)};try r.update {$0.guests = [Guest(name:"A")]};let original = try Data(contentsOf:r.file);XCTAssertThrowsError(try r.restore(Data("{broken".utf8)));var bad = WeddingArchive();bad.schema = 999;XCTAssertThrowsError(try r.restore(JSONEncoder().encode(bad)));XCTAssertEqual(try Data(contentsOf:r.file),original)}
    func testInvalidMutationLeavesArchiveUntouched() throws {let r = repository();defer {try? FileManager.default.removeItem(at:r.directory)};try r.update {$0.settings.location = "Roma"};let original = try Data(contentsOf:r.file);XCTAssertThrowsError(try r.update {$0.guests = [Guest(name:"")]});XCTAssertEqual(try Data(contentsOf:r.file),original)}
    func testCorruptExistingArchiveFailsClosed() throws {let r = repository();defer {try? FileManager.default.removeItem(at:r.directory)};try FileManager.default.createDirectory(at:r.directory,withIntermediateDirectories:true);let data = Data("invalid".utf8);try data.write(to:r.file);XCTAssertThrowsError(try r.update {$0.settings.names = "Overwrite"});XCTAssertEqual(try Data(contentsOf:r.file),data)}
}
